window.MARMOSET_BOOTSTRAP="";
(() => {
  'use strict';
  const clamp=(v,min,max)=>Math.min(max,Math.max(min,v));
  const number=v=>Number.isFinite(v)?new Intl.NumberFormat('ja-JP',{maximumSignificantDigits:5}).format(v):'—';
  const hexRgb=color=>[1,3,5].map(i=>parseInt(color.slice(i,i+2),16));
  const validColor=color=>typeof color==='string'&&/^#[0-9a-f]{6}$/i.test(color);
  const finite=value=>typeof value==='number'&&Number.isFinite(value);
  function el(tag,className,text){const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node;}

  window.createMsiViewer=({root,data,section,onSingleMolecule})=>{
    const $=id=>root.querySelector('#'+id),canvas=$('mx-msi-canvas'),surface=$('mx-msi-surface'),controls=$('mx-msi-controls');
    if(!canvas||!surface||!controls)throw Error('MSIの表示領域が見つかりません');
    const storageKey='marmoset-msi-display-v1',molecules=data.molecules,moleculeIds=new Set(molecules.map(m=>m.id));
    const state={mode:'single',single:molecules[0].id,layers:{},ranges:{},rangeExpanded:false};
    for(const m of molecules)state.layers[m.id]={visible:m.id==='5-HT'||m.id==='DA',color:validColor(m.color)?m.color:'#ffffff',opacity:100};
    try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved){if(['single','overlay'].includes(saved.mode))state.mode=saved.mode;if(moleculeIds.has(saved.single))state.single=saved.single;if(typeof saved.rangeExpanded==='boolean')state.rangeExpanded=saved.rangeExpanded;for(const m of molecules){const value=saved.layers?.[m.id];if(value){state.layers[m.id].visible=typeof value.visible==='boolean'?value.visible:state.layers[m.id].visible;if(validColor(value.color))state.layers[m.id].color=value.color;if(finite(value.opacity))state.layers[m.id].opacity=clamp(value.opacity,0,100);}}if(saved.ranges&&typeof saved.ranges==='object'&&!Array.isArray(saved.ranges))state.ranges=saved.ranges;}}catch{}
    let currentSection=section,frame=0,destroyed=false;
    const nativeCanvas=document.createElement('canvas');
    const message=el('div','mx-msi-message');message.hidden=true;surface.append(message);
    const save=()=>{try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{}};
    const current=()=>data.sections[currentSection];
    const rangeKey=id=>currentSection+'|'+id;
    const stats=id=>current().ranges[id]||{min:0,max:0,p99:0,valid:0,missing:current().x.length};
    function range(id){const saved=state.ranges[rangeKey(id)],s=stats(id),preset=['full','p99','manual'].includes(saved?.preset)?saved.preset:'full';if(preset==='manual'&&finite(saved.min)&&finite(saved.max)&&saved.min<saved.max)return {preset,min:saved.min,max:saved.max};const min=Math.min(0,finite(s.min)?s.min:0),candidate=preset==='p99'?s.p99:s.max;return {preset:preset==='manual'?'full':preset,min,max:finite(candidate)&&candidate>min?candidate:min+1};}
    function selected(){return state.mode==='single'?[state.single]:molecules.filter(m=>state.layers[m.id].visible).map(m=>m.id);}
    function updateRangeSummary(){const summary=controls.querySelector('.mx-msi-range-summary-values');if(summary)summary.textContent=selected().map(id=>{const r=range(id);return id+' '+number(r.min)+'–'+number(r.max);}).join(' / ')||'表示する分子を選択';}
    function schedule(){if(frame||destroyed)return;frame=requestAnimationFrame(()=>{frame=0;draw();});}
    function draw(){const s=current(),rect=canvas.getBoundingClientRect();if(!s||!rect.width||!rect.height)return;const active=selected(),layers=active.map(id=>({id,values:s.values[id]||[],color:hexRgb(state.layers[id].color),opacity:state.layers[id].opacity/100,range:range(id)}));
      nativeCanvas.width=s.width;nativeCanvas.height=s.height;const nativeContext=nativeCanvas.getContext('2d'),pixels=nativeContext.createImageData(s.width,s.height);
      if(layers.length)for(let i=0;i<s.x.length;i++){let valid=0,r=0,g=0,b=0;for(const layer of layers){const value=layer.values[i];if(!finite(value))continue;valid++;const normalized=clamp((value-layer.range.min)/(layer.range.max-layer.range.min),0,1)*layer.opacity;r+=layer.color[0]*normalized;g+=layer.color[1]*normalized;b+=layer.color[2]*normalized;}const offset=(s.y[i]*s.width+s.x[i])*4;pixels.data[offset]=valid?Math.round(Math.min(255,r)):53;pixels.data[offset+1]=valid?Math.round(Math.min(255,g)):62;pixels.data[offset+2]=valid?Math.round(Math.min(255,b)):72;pixels.data[offset+3]=255;}
      nativeContext.putImageData(pixels,0,0);const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);const fit=Math.min(rect.width/s.displayWidth,rect.height/s.displayHeight),left=(rect.width-s.displayWidth*fit)/2,top=(rect.height-s.displayHeight*fit)/2,[a,b,c,d,e,f]=s.matrix;ctx.imageSmoothingEnabled=false;ctx.setTransform(dpr*fit*a,dpr*fit*b,dpr*fit*c,dpr*fit*d,dpr*(left+fit*e),dpr*(top+fit*f));ctx.drawImage(nativeCanvas,0,0);ctx.setTransform(1,0,0,1,0,0);
      const title=active.length?active.join(' + '):'表示する分子を選択';$('mx-msi-heading').textContent='MSI / '+title;canvas.setAttribute('aria-label',currentSection+' '+title+'、生信号 a.u.、'+(state.mode==='overlay'?'色を加算して重ね合わせ':'単一分子'));$('mx-msi-summary').textContent='生信号（a.u.） · '+(state.mode==='overlay'?'色の加算合成':'単一分子')+' · '+s.x.length.toLocaleString()+'測定点';message.hidden=active.length>0;message.textContent='重ね合わせる分子を選択してください';
    }
    function render(){controls.replaceChildren();const bar=el('div','mx-msi-toolbar'),modeLabel=el('label','mx-msi-field','表示方法'),mode=el('select');mode.setAttribute('aria-label','MSIの表示方法');for(const[value,text]of[['single','単一分子'],['overlay','重ね合わせ']]){const option=el('option','',text);option.value=value;mode.append(option);}mode.value=state.mode;mode.addEventListener('change',()=>{state.mode=mode.value;save();render();schedule();if(state.mode==='single')onSingleMolecule?.(state.single);});modeLabel.append(mode);bar.append(modeLabel);
      if(state.mode==='single'){const label=el('label','mx-msi-field','分子'),select=el('select');select.setAttribute('aria-label','MSIの分子');for(const m of molecules){const option=el('option','',m.label||m.id);option.value=m.id;select.append(option);}select.value=state.single;select.addEventListener('change',()=>{state.single=select.value;save();render();schedule();onSingleMolecule?.(state.single);});label.append(select);bar.append(label);}
      const reset=el('button','mx-msi-reset','この切片のレンジを自動に');reset.type='button';reset.addEventListener('click',()=>{for(const m of molecules)delete state.ranges[rangeKey(m.id)];save();render();schedule();});controls.append(bar);
      if(state.mode==='overlay'){const choices=el('div','mx-msi-molecules');for(const m of molecules){const label=el('label','mx-msi-choice'),check=el('input');check.type='checkbox';check.checked=state.layers[m.id].visible;check.setAttribute('aria-label',m.id+'をMSIに重ねる');check.addEventListener('change',()=>{state.layers[m.id].visible=check.checked;save();render();schedule();});const dot=el('span','mx-msi-dot');dot.style.backgroundColor=state.layers[m.id].color;label.append(check,dot,document.createTextNode(m.label||m.id));choices.append(label);}controls.append(choices);}
      const disclosure=el('details','mx-msi-range-disclosure');disclosure.open=state.rangeExpanded;const summary=el('summary'),hint=el('span','mx-msi-range-summary-hint',state.rangeExpanded?'閉じる':'開く');summary.setAttribute('aria-label','MSIのレンジ調整');summary.append(el('strong','','MSI表示レンジ'),hint,el('span','mx-msi-range-summary-values'));const body=el('div','mx-msi-range-body');body.append(reset);disclosure.append(summary,body);disclosure.addEventListener('toggle',()=>{if(!disclosure.isConnected)return;state.rangeExpanded=disclosure.open;hint.textContent=state.rangeExpanded?'閉じる':'開く';save();});controls.append(disclosure);
      const layers=el('div','mx-msi-layers');for(const id of selected())layers.append(layerControls(id));body.append(layers);
      const help=el('p','mx-msi-note','生信号の表示範囲を調整します。範囲外の値は端の色に収まり、元の値は変わりません。黒：表示下限以下。灰色：表示中の分子がすべて欠測。背景：未測定。');body.append(help);if(state.mode==='overlay')body.append(el('p','mx-msi-note','重ね合わせは色の加算です。欠測の分子は加算せず、分子ごとに異なるレンジで表示します。色の強さは分子間の濃度比較には使えません。'));updateRangeSummary();
    }
    function layerControls(id){const layer=state.layers[id],s=stats(id),r=range(id),box=el('section','mx-msi-layer');box.setAttribute('aria-label',id+'のMSI表示調整');const top=el('div','mx-msi-layer-top'),colorLabel=el('label','mx-msi-color'),colorInput=el('input');colorInput.type='color';colorInput.value=layer.color;colorInput.setAttribute('aria-label',id+'のMSI表示色');colorInput.addEventListener('input',()=>{layer.color=colorInput.value;save();schedule();controls.querySelectorAll('.mx-msi-choice').forEach(choice=>{const input=choice.querySelector('input');if(input?.getAttribute('aria-label')===id+'をMSIに重ねる')choice.querySelector('.mx-msi-dot').style.backgroundColor=layer.color;});});colorLabel.append(colorInput,el('strong','',id));top.append(colorLabel);
      const opacityLabel=el('label','mx-msi-opacity'),opacityText=el('span','','不透明度 '+layer.opacity+'%'),opacity=el('input');opacity.type='range';opacity.min='0';opacity.max='100';opacity.step='1';opacity.value=String(layer.opacity);opacity.setAttribute('aria-label',id+'のMSI不透明度');opacity.addEventListener('input',()=>{layer.opacity=Number(opacity.value);opacityText.textContent='不透明度 '+layer.opacity+'%';save();schedule();});opacityLabel.append(opacityText,opacity);top.append(opacityLabel);box.append(top);
      const grid=el('div','mx-msi-range-grid'),minLabel=el('label','mx-msi-field','下限'),maxLabel=el('label','mx-msi-field','上限'),minInput=el('input'),maxInput=el('input');for(const[input,text,value]of[[minInput,'下限',r.min],[maxInput,'上限',r.max]]){input.type='number';input.step='any';input.value=String(value);input.setAttribute('aria-label',id+'のMSI表示'+text);}minLabel.append(minInput);maxLabel.append(maxInput);const presetLabel=el('label','mx-msi-field','レンジ'),preset=el('select');preset.setAttribute('aria-label',id+'のMSI表示レンジ');for(const[value,text]of[['full','自動：全範囲'],['p99','自動：上位1%を飽和'],['manual','手動']]){const option=el('option','',text);option.value=value;preset.append(option);}preset.value=r.preset;presetLabel.append(preset);grid.append(minLabel,maxLabel,presetLabel);box.append(grid);
      const sliders=el('div','mx-msi-range-sliders'),minSlider=el('input'),maxSlider=el('input');for(const[input,name]of[[minSlider,'下限'],[maxSlider,'上限']]){input.type='range';input.setAttribute('aria-label',id+'のMSI表示'+name+'スライダー');}sliders.append(minSlider,maxSlider);box.append(sliders);const error=el('p','mx-msi-range-error');error.setAttribute('role','alert');error.hidden=true;const status=el('p','mx-msi-range-status');box.append(error,status);
      function sync(next,preserveDraft=false){const lo=Math.min(0,s.min??0,next.min),hi=Math.max(s.max??0,next.max,lo+1),step=(hi-lo)/1000;if(!preserveDraft||document.activeElement!==minInput)minInput.value=String(next.min);if(!preserveDraft||document.activeElement!==maxInput)maxInput.value=String(next.max);preset.value=next.preset;for(const input of[minSlider,maxSlider]){input.min=String(lo);input.max=String(hi);input.step=String(step);}minSlider.value=String(next.min);maxSlider.value=String(next.max);status.textContent='表示 '+number(next.min)+'–'+number(next.max)+' a.u. · '+(s.valid?('有効 '+s.valid.toLocaleString()+'点'+(s.missing?' / 欠測 '+s.missing.toLocaleString()+'点':'')+(s.min===0&&s.max===0?' · 全て0':'')):'有効値なし');updateRangeSummary();}
      function manual(min,max,preserveDraft=false){if(!finite(min)||!finite(max)||min>=max){error.hidden=false;error.textContent='有限の数値で、下限 < 上限にしてください。';return false;}error.hidden=true;state.ranges[rangeKey(id)]={preset:'manual',min,max};sync(range(id),preserveDraft);save();schedule();return true;}
      const numeric=preserveDraft=>manual(minInput.value.trim()===''?NaN:Number(minInput.value),maxInput.value.trim()===''?NaN:Number(maxInput.value),preserveDraft);for(const input of[minInput,maxInput]){input.addEventListener('input',()=>numeric(true));input.addEventListener('change',()=>numeric(false));}
      minSlider.addEventListener('input',()=>{const currentRange=range(id),step=Number(minSlider.step),min=Math.min(Number(minSlider.value),currentRange.max-step);manual(min,currentRange.max);});maxSlider.addEventListener('input',()=>{const currentRange=range(id),step=Number(maxSlider.step),max=Math.max(Number(maxSlider.value),currentRange.min+step);manual(currentRange.min,max);});
      preset.addEventListener('change',()=>{if(preset.value==='manual'){const currentRange=range(id);state.ranges[rangeKey(id)]={...currentRange,preset:'manual'};}else state.ranges[rangeKey(id)]={preset:preset.value};error.hidden=true;sync(range(id));save();schedule();});sync(r);if(!s.valid)for(const input of[minInput,maxInput,minSlider,maxSlider,preset])input.disabled=true;return box;
    }
    canvas.hidden=false;$('mx-msi-image').hidden=true;const observer=new ResizeObserver(schedule);observer.observe(surface);render();schedule();
    return {
      singleMolecule(){return state.mode==='single'?state.single:null;},
      showMolecule(id){
        if(!moleculeIds.has(id))return;
        state.mode='single';state.single=id;save();render();schedule();
      },
      setSection(id){if(id===currentSection)return;if(!data.sections[id])throw Error('MSI切片が見つかりません：'+id);currentSection=id;render();schedule();},redraw:schedule,destroy(){destroyed=true;if(frame)cancelAnimationFrame(frame);observer.disconnect();message.remove();}};
  };
})();
